def apply_discount(subtotal, discount_code=None):
    """Apply a discount code to a subtotal if provided.

    Args:
        subtotal: The original subtotal.
        discount_code: The discount code string. If None or empty, no discount is applied.

    Returns:
        The discounted amount rounded to 2 decimal places.
    """
    if not discount_code:
        return round(float(subtotal), 2)

    if discount_code == "FLAT5":
        return round(float(subtotal) - 5.00, 2)

    discount_percent = DISCOUNT_CODES.get(discount_code.upper())
    if discount_percent is None:
        return round(float(subtotal), 2)

    discount_amount = float(subtotal) * (discount_percent / 100)
    return round(float(subtotal) - discount_amount, 2)

def apply_discount(subtotal, discount_code, applied_discounts=None):
    """Apply a discount code to a subtotal if not already applied.

    Args:
        subtotal: The original subtotal.
        discount_code: The discount code string.
        applied_discounts: Set of discount codes already applied to prevent duplicates.

    Returns:
        The discounted subtotal.
    """
    if applied_discounts is None:
        applied_discounts = set()
    if discount_code in applied_discounts:
        return subtotal
    applied_discounts.add(discount_code)

    if not discount_code:
        return subtotal

    if discount_code not in DISCOUNT_CODES:
        raise ValueError("Invalid discount code")

    discount_value = DISCOUNT_CODES[discount_code]

    if discount_code == "FLAT5":
        return max(0, subtotal - discount_value)
    else:
        return subtotal * (1 - discount_value / 100)
